// Claude Sitcom: one mockumentary episode per topic, built by lessons/engine/build.py --variant app
// into public/lessons/sitcom-<topicId>.html (+ sitcom-<topicId>-narration.mp3). The list of built
// episodes is generated by scripts/gen-registry.mjs (runs before dev/build), so a newly built
// episode appears in the app automatically.
import { CLAUDE_SITCOM_GUIDE_BUILT, CLAUDE_SITCOM_IDS } from "./generated/claudeSitcoms";

/** Topic ids that have a built Claude Sitcom episode. */
export const CLAUDE_SITCOMS: ReadonlySet<string> = new Set(CLAUDE_SITCOM_IDS);

/** The episode guide page (lessons/engine/sitcom_index.py), shown only once it has been built. */
export const CLAUDE_SITCOM_GUIDE: string | null = CLAUDE_SITCOM_GUIDE_BUILT ? "/lessons/claude-sitcom.html" : null;

export const claudeSitcomHref = (topicId: string) => `/lessons/sitcom-${encodeURIComponent(topicId)}.html`;

/** Store key for one finished scene: one star each, once. Also how the player learns which scenes to tick. */
export const claudeSitcomSceneKey = (topicId: string, sceneId: string) => `claude-sitcom:${topicId}:${sceneId}`;

/** Messages the episode page (?embed=1) posts to the app (see lessons/engine/engine.js). */
export type ClaudeSitcomMessage =
  | { source: "y8-lesson"; topic: string; type: "hello"; chapters: unknown }
  | { source: "y8-lesson"; topic: string; type: "height"; value: unknown }
  | { source: "y8-lesson"; topic: string; type: "chapter-done"; chapter: unknown }
  | { source: "y8-lesson"; topic: string; type: "complete" }
  | { source: "y8-lesson"; topic: string; type: "theater"; on: unknown };
